CommonCacheResources = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=CommonCacheResources]");
        var resourceData = await CommonCacheResources.getDataSource("ContentManagement/CommonObject/Latest()?type=ContentManagement/Resource&$filter=Culture eq ''&$orderby=Name asc");
        await CommonCacheResources.setupResourceGrid(resourceData, container);
    },

    getDataSource(url) {
        return new kendo.data.DataSource({
            transport: {
                read: { url: api.apiRoot + url, dataType: "json" }
            },
            pageSize: 50,
            schema: {
                data: function (response) {
                    for(let i = 0; i < response.value.length; i = i + 1) {
                        response.value[i].CreatedOn = new Date(response.value[i].CreatedOn);
                        response.value[i].LastUpdated = new Date(response.value[i].LastUpdated);
                        response.value[i].Entity = JSON.parse(response.value[i].Json); 
                    }
                    return response.value;
                },
                total: function(response) {
                    return response.value.length;
                }
            }
        });;
    },

	escapeHtml: function(html) {
    	return html.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;');
	},

    setupResourceGrid: async function (ds, container) {
        var cacheGrid = new GridWidget(container, ds);
        cacheGrid.groupable = false;
        cacheGrid.filterable = true;
        cacheGrid.editable = true;
        cacheGrid.commandWidth = 100;
        cacheGrid.columns = [
            { 
                field: "Entity.Key", 
                editable: false, 
                title: "[resource_shortdisplayname[Key]]",				
                width: "[theme[columns.small]]"
            },
            { 
                field: "Name", 
                editable: false, 
                title: "[resource_shortdisplayname[Name]]", 
				width: "[theme[columns.small]]"  
            },
			{ 
                field: "Entity.DisplayName", 
                title: "[resource_shortdisplayname[displayname]]", 
                template: "#=(Entity.DisplayName && Entity.DisplayName.length > 80) ? CommonCacheResources.escapeHtml(Entity.DisplayName.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(Entity.DisplayName)#", encoded: true },
			{ 
                field: "Entity.ShortDisplayName", 
                title: "[resource_shortdisplayname[shortdisplayname]]", 
                template: "#=(Entity.ShortDisplayName && Entity.ShortDisplayName.length > 80) ? CommonCacheResources.escapeHtml(Entity.ShortDisplayName.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(Entity.ShortDisplayName)#", 
                encoded: true, 
				width: "[theme[columns.small]]" 
            },
			{ 
                field: "Entity.Description", 
                title: "[resource_shortdisplayname[description]]", 
                template: "#=(Entity.Description && Entity.Description.length > 80) ? CommonCacheResources.escapeHtml(Entity.Description.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(Entity.Description)#", 
                encoded: true 
            },
            { 
                field: "LastUpdated", 
                title: "[resource_displayname[lastupdated]]", 
                type: "date", 
                format: "{0: " + type.dateFormat + " HH:mm}", 
				width: "[theme[columns.small]]"
            },
            { 
                field: "LastUpdatedBy", 
                title: "[resource_displayname[lastupdatedby]]", 
				width: "[theme[columns.small]]"
            },
        ];
        cacheGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        cacheGrid.commands.push({ name: "remove", icon: "k-i-trash", text: "[resource_displayname[remove]]" });
        cacheGrid.toolbar = "<button class='btn btn-sm btn-primary' name='add'><span class='k-icon k-i-plus'></span> [resource_displayname[add]]</button>";
        cacheGrid.dataBound = function (e) {
            $("[name=save]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheResources.save(e, cacheGrid));
            $("[name=remove]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheResources.removeFromCache(e, cacheGrid));
        };
        cacheGrid.detailTemplate = "<div name='translationsGrid'></div>";
        cacheGrid.detailExpand = async (e) => await CommonCacheResources.expandResourceGrid(e, cacheGrid);
        await cacheGrid.init();
        $("[name=add]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheResources.newResource(e, cacheGrid));
        cacheGrid.kendoObject.dataSource.group({ field: "Entity.Key" });
    },


    save: async function(e, grid) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        var dupe = JSON.parse(JSON.stringify(item));
        dupe.Entity.Key = dupe.Key;
        dupe.Json = JSON.stringify(dupe.Entity);
        delete dupe.Entity;
        await api.update("ContentManagement/CommonObject(" + item.Id + ")", dupe).then(async () => {
            notification.success("[resource_displayname[saved]]");
            await api.get("RefreshCache").then(() => notification.success("[resource_displayname[rebuilt]]"));
        }).catch((err) => error(err));
    },

    removeFromCache: async function (e, grid) {
        var item = grid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
        await api.destroy("ContentManagement/CommonObject(" + item.Id + ")").then(async () => {
            notification.success("[resource_displayname[deleted]]");
            await api.get("RefreshCache").then(() => {
                notification.success("[resource_displayname[rebuilt]]")
                grid.refresh();
            }).catch((err) => error(err));
        }).catch((err) => error(err));
    },


    expandResourceGrid: async function (e, grid) {
        var container = $(e.detailRow);
        if($(container).attr("expanded") === "true") { return; }
        $(container).attr("expanded", "true");
        var resource = grid.dataItem(e.masterRow).Entity;
        var translations = await CommonCacheResources.getDataSource("ContentManagement/CommonObject/Latest()?type=ContentManagement/Resource&$filter=Name eq '" + resource.Name + "' and Culture ne '' and Key eq '" + resource.Key + "'");
        var subGrid = new GridWidget($("[name=translationsGrid]", container), translations);
        subGrid.pageable = false;
        subGrid.groupable = false;
        subGrid.toolbar = "<div><button name='createTranslation'><span class='k-icon k-i-plus'></span>[resource_displayname[NewTranslation]]</button></div>";
        subGrid.columns = [
            { field: "Culture", editable: false, title: "[resource_shortdisplayname[Culture]]", width: 100 },
            { field: "Name", editable: false, title: "[resource_shortdisplayname[Name]]", width: 200 },
			{ field: "Entity.DisplayName", title: "[resource_shortdisplayname[displayname]]", template: "#=(Entity.DisplayName && Entity.DisplayName.length > 80) ? CommonCacheResources.escapeHtml(Entity.DisplayName.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(Entity.DisplayName)#", encoded: true },
			{ field: "Entity.ShortDisplayName", title: "[resource_shortdisplayname[shortdisplayname]]", template: "#=(Entity.ShortDisplayName && Entity.ShortDisplayName.length > 80) ? CommonCacheResources.escapeHtml(Entity.ShortDisplayName.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(Entity.ShortDisplayName)#", encoded: true },
			{ field: "Entity.Description", title: "[resource_shortdisplayname[description]]", template: "#=(Entity.Description && Entity.Description.length > 80) ? CommonCacheResources.escapeHtml(Entity.Description.substring(0, 80)) + '...' : CommonCacheResources.escapeHtml(Entity.Description)#", encoded: true },
            { field: "LastUpdated", title: "[resource_displayname[lastupdated]]", width: 120, type: "date", format: "{0: " + type.dateFormat + " HH:mm}" },
            { field: "LastUpdatedBy", title: "[resource_displayname[lastupdatedby]]", width: 200 },
        ];
        subGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_shortdisplayname[save]]" });
        subGrid.commands.push({ name: "destroy", icon: "k-i-trash", text: "[resource_shortdisplayname[delete]]" });
        subGrid.dataBound = async function () {
            $("[name=save]", subGrid.gridElement).on("click", async (e) => await CommonCacheResources.save(e, subGrid));
            $("[name=destroy]", subGrid.gridElement).on("click", async (e) => await CommonCacheResources.deleteTranslation(e, subGrid));
        };
        await subGrid.init();
        $("button[name=createTranslation]", subGrid.gridElement).on("click", async function (e) { await CommonCacheResources.createTranslation(e, subGrid, resource); });
    },


    deleteTranslation: async function (e, grid) {
        e.preventDefault();
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        await api.destroy("ContentManagement/CommonObject(" + item.Id + ")").then(async () => {
            await api.get("RefreshCache").then(() => {
                notification.success("[resource_displayname[rebuilt]]");
                grid.refresh();
                notification.success("[resource_displayname[deleted]]");
            }).catch((err) => error(err));
        }).catch((err) => error(err));
    },

    createTranslation: async function (e, grid, item) {
        e.preventDefault();
        var translations = (await api.get("ContentManagement/CommonObject/Latest()?type=ContentManagement/Resource&$filter=Name eq '" + item.Name + "' and Key eq '" + item.Key + "'")).value;
        var cultures = (await api.get("ContentManagement/Culture")).value;
        var options = cultures.filter((c) => c.Id !== "" && translations.filter((r)  => r.Culture === c.Id).length === 0);
        var createTranslationDialog = new Dialog({ width: 520, height: "auto", title: "[resource_displayname[newtranslation]]" });
        createTranslationDialog.template = $("[name=createTranslationDialog]").html();
        createTranslationDialog.events.confirm = async function (e) {
            var resource = {
                Culture: culture.data("kendoDropDownList").value(),
                Key: item.Key,
                Name: item.Name,
                DisplayName: $("[name=displayName]", createTranslationDialog.element).val(),
                ShortDisplayName: $("[name=shortDisplayName]", createTranslationDialog.element).val(),
                Description: $("[name=description]", createTranslationDialog.element).val()
            };
            var commonObject = {
                Id: 0,
                Key: resource.Key,
                Name: resource.Name,
                CreatedOn: resource.CreatedOn,
                LastUpdated: resource.LastUpdated,
                Json: JSON.stringify(resource),
                Type: "ContentManagement/Resource",
                Culture: resource.Culture,
                Version: 1
            };
            await api.add("ContentManagement/CommonObject", commonObject).then(async () => {
                notification.success("[resource_displayname[added]]");
                await api.get("RefreshCache")
                    .then(() => {
                        notification.success("[resource_displayname[rebuilt]]");
                        grid.refresh();
                    })
                    .catch((err) => error(err));
                createTranslationDialog.events.close();
            }).catch((err) => error(err));
        };
        createTranslationDialog.init(() => {
            culture = $("[name=culture]", createTranslationDialog.element).kendoDropDownList({ dataTextField: "Name", dataValueField: "Id", dataSource: options, index: 0 });
        });
    },

    newResource: async function (e, cacheGrid) {
        e.preventDefault();
        var newResourceDialog = new Dialog({ width: 520, height: "auto", title: "[resource_displayname[newresource]]" });
        newResourceDialog.template = $("[name=newResourceDialog]").html();
        newResourceDialog.events.create = async function (e) {
            var resource = {
                Name: $("[name=name]", newResourceDialog.element).val(),
                Key: $("[name=key]", newResourceDialog.element).val(),
                DisplayName: $("[name=displayName]", newResourceDialog.element).val(),
                ShortDisplayName: $("[name=shortDisplayName]", newResourceDialog.element).val(),
                Description: $("[name=description]", newResourceDialog.element).val(),
                CreatedOn: (new Date()).toISOString(),
                LastUpdated: (new Date()).toISOString(),
                Culture: ""
            };
            var commonObject = {
                Id: 0, Name: resource.Name,
                Key: resource.Key,
                CreatedOn: resource.CreatedOn,
                LastUpdated: resource.LastUpdated,
                Json: JSON.stringify(resource),
                Type: "ContentManagement/Resource",
                Culture: resource.Culture,
                Version: 1
            };
            await api.add("ContentManagement/CommonObject", commonObject).then(async () => {
                notification.success("[resource_displayname[added]]");
                await api.get("RefreshCache").then(() => notification.success("[resource_displayname[rebuilt]]"));
                cacheGrid.refresh();
            }).catch((err) => error(err));
            newResourceDialog.events.close();
        };
        newResourceDialog.init();
    }
}
